"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import type { DiaxRelation } from "diax";
import {
  Bot,
  Braces,
  Database,
  FileCode2,
  Globe2,
  Languages,
  type LucideIcon,
  ScanSearch,
  Settings2,
  Sparkles,
  Terminal,
  Workflow,
} from "lucide-react";
import type { ReactNode } from "react";

const outerTargets = {
  source: "compiler-source",
  policy: "compiler-policy",
  core: "compiler-core",
  output: "compiler-output",
} as const;

const stages = [
  {
    id: "stage-scan",
    eyebrow: "01 · Parse",
    title: "Scan source syntax",
    detail: "Vue SFC · JSX · TypeScript",
    icon: ScanSearch,
    className: "sm:col-start-1 sm:row-start-1",
  },
  {
    id: "stage-translate",
    eyebrow: "02 · Enrich",
    title: "Generate semantic keys",
    detail: "Context-aware AI suggestions",
    icon: Bot,
    className: "sm:col-start-2 sm:row-start-1",
  },
  {
    id: "stage-rewrite",
    eyebrow: "03 · Transform",
    title: "Rewrite expressions",
    detail: "Deterministic source patches",
    icon: Braces,
    className: "sm:col-start-3 sm:row-start-1",
  },
  {
    id: "stage-catalog",
    eyebrow: "04 · Materialize",
    title: "Build locale catalog",
    detail: "Namespaced incremental JSON",
    icon: Languages,
    className: "sm:col-start-3 sm:row-start-2",
  },
  {
    id: "stage-validate",
    eyebrow: "05 · Verify",
    title: "Check reversible output",
    detail: "Duplicate · lint · source map",
    icon: Sparkles,
    className: "sm:col-start-2 sm:row-start-2",
  },
  {
    id: "stage-export",
    eyebrow: "06 · Deliver",
    title: "Publish review artifacts",
    detail: "Patch · catalog · diagnostics",
    icon: Terminal,
    className: "sm:col-start-1 sm:row-start-2",
  },
] as const;

const outerRelations = [
  relation("source-core", outerTargets.source, outerTargets.core, <WireLabel>source</WireLabel>),
  relation("policy-core", outerTargets.policy, outerTargets.core, <WireLabel>policy</WireLabel>),
  relation("core-output", outerTargets.core, outerTargets.output, <WireLabel>artifacts</WireLabel>),
] as const satisfies readonly DiaxRelation<ReactNode>[];

const pipelineRelations = stages
  .slice(0, -1)
  .map((stage, index) => relation(`pipeline-${index + 1}`, stage.id, stages[index + 1].id));

function relation(
  id: string,
  from: string,
  to: string,
  label?: ReactNode,
): DiaxRelation<ReactNode> {
  return {
    id,
    from,
    to,
    label,
    color: "#6f8fff",
    targetMarker: "arrow",
    gap: 7,
  };
}

const nodeClass =
  "relative min-w-0 border border-[#49609b] bg-[#101b38] text-[#f2f5ff] shadow-[0_10px_24px_rgb(2_8_26_/_0.34)] [border-radius:2px]";

export default function AiContentCompiler() {
  return (
    <figure
      data-showcase-corpus="ai-content-compiler"
      className="w-full max-w-[1120px] overflow-hidden border border-[#26396d] bg-[#09132e] p-3 text-[#f2f5ff] shadow-[0_24px_70px_rgb(2_8_26_/_0.38)] [border-radius:3px] sm:p-6"
    >
      <figcaption className="mb-5 flex flex-col justify-between gap-3 border-b border-[#26396d] pb-4 sm:flex-row sm:items-end">
        <div>
          <p className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-[#8da6ff]">
            Nested compiler scopes · Authored DOM
          </p>
          <h2 className="m-0 mt-1 text-xl font-semibold tracking-[-0.04em] sm:text-3xl">
            AI content compiler
          </h2>
          <p className="m-0 mt-1 max-w-2xl text-[10px] leading-relaxed text-[#aeb9d8] sm:text-xs">
            The outer surface explains system boundaries. A second local surface owns the six-stage
            compiler path inside the real pipeline panel.
          </p>
        </div>
        <dl className="m-0 flex gap-4 font-mono text-[8px] text-[#8f9ab8]">
          <Stat label="Surfaces" value="2" />
          <Stat label="Targets" value="10" />
          <Stat label="Anchors" value="0" />
        </dl>
      </figcaption>

      <ConnectionSurface
        relations={outerRelations}
        pathType="orthogonal"
        aria-label="AI content compiler system relationships"
        className="grid gap-16 border border-[#26396d] bg-[#0c1734] p-3 pb-16 [background-image:linear-gradient(rgb(111_143_255_/_0.055)_1px,transparent_1px),linear-gradient(90deg,rgb(111_143_255_/_0.055)_1px,transparent_1px)] [background-size:22px_22px] sm:grid-cols-[minmax(130px,.58fr)_minmax(0,1.84fr)_minmax(130px,.58fr)] sm:items-center sm:gap-14 sm:p-5 sm:pb-16"
      >
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-1 sm:gap-5">
          <BoundaryNode
            id={outerTargets.source}
            icon={FileCode2}
            eyebrow="Input 01"
            title="Application source"
            detail="JSX, templates and existing component semantics"
          />
          <BoundaryNode
            id={outerTargets.policy}
            icon={Settings2}
            eyebrow="Input 02"
            title="Language policy"
            detail="Glossary, naming rules and target locales"
          />
        </div>

        <article
          {...connectionTarget(outerTargets.core)}
          className={`${nodeClass} overflow-hidden border-[#718eff] bg-[#0d1938]`}
        >
          <header className="flex items-center justify-between gap-3 border-b border-[#314985] bg-[#13214a] px-3 py-2.5">
            <div className="flex min-w-0 items-center gap-2">
              <Workflow aria-hidden="true" className="size-4 shrink-0 text-[#8da6ff]" />
              <div className="min-w-0">
                <p className="m-0 font-mono text-[7px] font-bold uppercase tracking-[0.12em] text-[#8da6ff]">
                  Local surface / compiler-core
                </p>
                <h3 className="m-0 mt-0.5 truncate text-[10px] font-semibold sm:text-sm">
                  Deterministic transformation pipeline
                </h3>
              </div>
            </div>
            <code className="hidden border border-[#40578d] bg-[#0a1430] px-2 py-1 text-[7px] text-[#aeb9d8] sm:block">
              source → patch + catalog
            </code>
          </header>

          <ConnectionSurface
            relations={pipelineRelations}
            pathType="orthogonal"
            aria-label="Six-stage content compiler pipeline"
            className="grid gap-x-7 gap-y-14 p-3 pb-14 sm:grid-cols-3 sm:grid-rows-2 sm:p-4 sm:pb-14"
          >
            {stages.map((stage) => (
              <Stage key={stage.id} {...stage} />
            ))}
          </ConnectionSurface>
        </article>

        <BoundaryNode
          id={outerTargets.output}
          icon={Database}
          eyebrow="Output"
          title="Review bundle"
          detail="Reversible patch, locale catalog and diagnostics"
        />
      </ConnectionSurface>

      <section
        className="mt-4 grid border-y border-[#26396d] sm:grid-cols-3"
        aria-label="Compiler guarantees"
      >
        <Guarantee
          icon={Globe2}
          title="Framework-aware"
          detail="Retains existing component structure"
        />
        <Guarantee
          icon={Sparkles}
          title="AI-assisted"
          detail="Generation stays inside a typed pipeline"
        />
        <Guarantee
          icon={Terminal}
          title="Review-first"
          detail="Every output remains reproducible"
        />
      </section>
    </figure>
  );
}

function BoundaryNode({
  id,
  icon: Icon,
  eyebrow,
  title,
  detail,
}: {
  id: string;
  icon: LucideIcon;
  eyebrow: string;
  title: string;
  detail: string;
}) {
  return (
    <article {...connectionTarget(id)} className={`${nodeClass} p-2.5 sm:p-3`}>
      <Icon aria-hidden="true" className="size-4 text-[#8da6ff]" />
      <p className="m-0 mt-2 font-mono text-[6px] font-bold uppercase tracking-[0.12em] text-[#7785ad] sm:text-[7px]">
        {eyebrow}
      </p>
      <h3 className="m-0 mt-1 text-[9px] font-semibold sm:text-[11px]">{title}</h3>
      <p className="m-0 mt-1 text-[6px] leading-relaxed text-[#9ba7c6] sm:text-[8px]">{detail}</p>
    </article>
  );
}

function Stage({
  id,
  eyebrow,
  title,
  detail,
  icon: Icon,
  className,
}: {
  id: string;
  eyebrow: string;
  title: string;
  detail: string;
  icon: LucideIcon;
  className: string;
}) {
  return (
    <article {...connectionTarget(id)} className={`${nodeClass} p-2 ${className} sm:p-2.5`}>
      <div className="flex items-center gap-1.5">
        <Icon aria-hidden="true" className="size-3 shrink-0 text-[#8da6ff]" />
        <p className="m-0 font-mono text-[5px] font-bold uppercase tracking-[0.1em] text-[#7785ad] sm:text-[7px]">
          {eyebrow}
        </p>
      </div>
      <h4 className="m-0 mt-1.5 text-[7px] font-semibold sm:text-[10px]">{title}</h4>
      <p className="m-0 mt-1 text-[5px] leading-relaxed text-[#9ba7c6] sm:text-[7px]">{detail}</p>
    </article>
  );
}

function WireLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-[#40578d] bg-[#09132e] px-2 py-1 font-mono text-[6px] font-bold uppercase tracking-[0.08em] text-[#aebeff] sm:text-[8px]">
      {children}
    </span>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd className="m-0 mt-0.5 text-base font-semibold text-[#f2f5ff]">{value}</dd>
    </div>
  );
}

function Guarantee({
  icon: Icon,
  title,
  detail,
}: {
  icon: LucideIcon;
  title: string;
  detail: string;
}) {
  return (
    <div className="flex items-center gap-2 border-[#26396d] px-3 py-3 sm:border-l sm:first:border-l-0">
      <Icon aria-hidden="true" className="size-3.5 shrink-0 text-[#8da6ff]" />
      <span>
        <strong className="block text-[8px] font-semibold sm:text-[10px]">{title}</strong>
        <small className="mt-0.5 block text-[6px] text-[#8f9ab8] sm:text-[8px]">{detail}</small>
      </span>
    </div>
  );
}
